import{_ as t,o,c as d,a2 as a}from"./chunks/framework.Dx-TCpNt.js";const u=JSON.parse('{"title":"Keyboard Shortcuts","description":"One page for every key and mouse gesture. Single-key shortcuts are ignored while focus sits inside a text field, so typing a note never flips the view…","frontmatter":{"description":"One page for every key and mouse gesture. Single-key shortcuts are ignored while focus sits inside a text field, so typing a note never flips the view…"},"headers":[],"relativePath":"guide/shortcuts.md","filePath":"guide/shortcuts.md","lastUpdated":1794842635000}'),r={name:"guide/shortcuts.md"};function n(i,e,s,l,c,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>One page for every key and mouse gesture. Single-key shortcuts are ignored while focus sits inside a text field, so typing a note never flips the view mid-sentence.</p><h2 id="what-this-page-solves" tabindex="-1">What this page solves <a class="header-anchor" href="#what-this-page-solves" aria-label="Permalink to &quot;What this page solves&quot;">​</a></h2><p>Shortcuts are scattered across the library, the workbench, the compare reader and the notes editor. Rather than hunting through each chapter, keep this page open while you learn the workflow, or print it and tape it next to the monitor.</p><h2 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>[</code></td><td>Previous page (crosses chapter boundaries).</td></tr><tr><td><code>]</code></td><td>Next page (crosses chapter boundaries).</td></tr><tr><td><code>←</code> / <code>→</code></td><td>Previous / next page following the reading direction; vertical reading uses <code>↑</code> / <code>↓</code>.</td></tr><tr><td><code>P</code></td><td>Switch to the panel workbench.</td></tr><tr><td><code>C</code></td><td>Switch to the compare reader.</td></tr><tr><td><code>O</code></td><td>Switch to the original-page view.</td></tr><tr><td><code>S</code></td><td>Show or hide the library sidebar.</td></tr><tr><td><code>N</code></td><td>Show or hide the notes column.</td></tr><tr><td><code>E</code></td><td>Open the export dialog (when a page is open).</td></tr><tr><td><code>R</code></td><td>Enter or leave focus mode.</td></tr><tr><td><code>Esc</code></td><td>Leave focus mode (when no dialog is open).</td></tr><tr><td><code>?</code></td><td>Open the keyboard and actions help.</td></tr><tr><td><code>Ctrl+Z</code></td><td>Undo the last panel change.</td></tr><tr><td><code>Ctrl+Shift+Z</code></td><td>Redo.</td></tr><tr><td><code>Ctrl+Y</code></td><td>Redo (alternative).</td></tr></tbody></table><p>In read mode the editing shortcuts (<code>Ctrl+Z</code>, <code>Ctrl+Y</code>, save, panel and annotation keys) do nothing; page turning and the view switches still work.</p><h2 id="focus-mode" tabindex="-1">Focus mode <a class="header-anchor" href="#focus-mode" aria-label="Permalink to &quot;Focus mode&quot;">​</a></h2><p>Press <code>R</code> or click <code>⛶</code> in the top bar to enter: the top bar, stage toolbar, panel section rail and status bar fold away so the page fills the window. It does not change the edit/read mode. Leave with <code>Esc</code> (when no dialog is open), <code>R</code> again, or by double-clicking empty space on touch devices. The state is remembered across sessions. A short tip names the exit gesture on entry, then fades out and never covers the artwork.</p><h2 id="file" tabindex="-1">File <a class="header-anchor" href="#file" aria-label="Permalink to &quot;File&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+O</code></td><td>Open a project file (<code>.mnproj</code>).</td></tr><tr><td><code>Ctrl+S</code></td><td>Save the current page.</td></tr><tr><td><code>Ctrl+Shift+S</code></td><td>Save to the linked project file — writes the whole library back into the opened <code>.mnproj</code>.</td></tr></tbody></table><p>These file shortcuts work even while typing, matching desktop apps. In read-only mode, and when no project is linked, saving is refused with an explanation instead of writing.</p><p>There is no shortcut for <strong>File → Save as…</strong>: it always asks for a destination, so it stays a deliberate menu action.</p><h2 id="panel-workbench" tabindex="-1">Panel workbench <a class="header-anchor" href="#panel-workbench" aria-label="Permalink to &quot;Panel workbench&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key / gesture</th><th>Action</th></tr></thead><tbody><tr><td>Drag a box</td><td>Move the panel.</td></tr><tr><td>Drag a corner or edge handle</td><td>Resize in eight directions.</td></tr><tr><td>Double-click empty space</td><td>Add a default panel.</td></tr><tr><td>Drag on empty space</td><td>Draw a panel.</td></tr><tr><td><code>Shift</code> + drag</td><td>Constrain the new panel to a square.</td></tr><tr><td><code>Alt</code> + drag</td><td>Disable snapping.</td></tr><tr><td><code>Ctrl</code>-click / <code>Shift</code>-click</td><td>Add or remove a panel from the selection.</td></tr><tr><td>Arrow keys</td><td>Nudge the selection by 0.2% of the page.</td></tr><tr><td><code>Shift</code> + arrow keys</td><td>Nudge by 1%.</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>Delete the selected panels (or the selected annotation).</td></tr><tr><td><code>Enter</code></td><td>Save (Confirm mode).</td></tr><tr><td><code>Esc</code></td><td>Discard changes (Confirm mode); otherwise leave the annotation tool or deselect a mark.</td></tr></tbody></table><p>The annotation toolbar has no letter shortcuts; it is mouse-only. <code>Esc</code> always backs out one level: selected annotation → current tool → dirty page.</p><h2 id="compare-reader" tabindex="-1">Compare reader <a class="header-anchor" href="#compare-reader" aria-label="Permalink to &quot;Compare reader&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key / gesture</th><th>Action</th></tr></thead><tbody><tr><td><code>H</code></td><td>Mask everything (turn the mask master switch on).</td></tr><tr><td><code>Shift+H</code></td><td>Reveal everything (turn the mask master switch off).</td></tr><tr><td>Drag a pane</td><td>Pan that language.</td></tr><tr><td>Wheel over a pane</td><td>Zoom that language.</td></tr><tr><td><code>Alt</code> + drag / wheel</td><td>Apply the gesture to the current panel only.</td></tr><tr><td>Click a masked pane</td><td>Reveal it temporarily; click again to mask it.</td></tr></tbody></table><p>Panel navigation uses the <strong>Previous panel</strong> / <strong>Next panel</strong> buttons; they are not bound to keys because <code>[</code> and <code>]</code> already change pages.</p><h2 id="notes-editor" tabindex="-1">Notes editor <a class="header-anchor" href="#notes-editor" aria-label="Permalink to &quot;Notes editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+B</code></td><td>Bold.</td></tr><tr><td><code>Ctrl+I</code></td><td>Italic.</td></tr><tr><td><code>Ctrl+K</code></td><td>Insert a link.</td></tr><tr><td><code>Ctrl+Enter</code></td><td>Save the note (or save the scratchpad).</td></tr><tr><td><code>Enter</code> in the tag field</td><td>Add the tag.</td></tr><tr><td><code>Tab</code></td><td>Indent inside the editor.</td></tr></tbody></table><h2 id="mouse-only-actions" tabindex="-1">Mouse-only actions <a class="header-anchor" href="#mouse-only-actions" aria-label="Permalink to &quot;Mouse-only actions&quot;">​</a></h2><p>Some controls have no keyboard equivalent by design:</p><ul><li>Pane splitters and the detail-view divider: drag to resize; the divider also moves with the arrow keys when focused.</li><li>Language chip reordering in the compare reader: drag a chip.</li><li>Zoom buttons: <code>−</code> / <code>＋</code> in the panel toolbar.</li><li>Panel template and alignment preset pickers.</li><li>Right-click menus: a mark, a compare pane, or a panel in the detail view. The pane menu holds the enlarged viewer, masking, single-panel PNG, panel number and link commands.</li><li>Dragging the artwork in the detail view to align it, and the <strong>Sync move</strong> switch.</li><li>Clicking the save indicator to open the write-back status panel.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>A shortcut types a letter instead.</strong> Focus is in an input, textarea or contenteditable element. Click the stage first.</li><li><strong><code>H</code> does not mask.</strong> The focus is in a note or toolbar field; the compare shortcut is ignored while typing.</li><li><strong><code>E</code> does nothing.</strong> No page is open, so the export dialog is unavailable.</li><li><strong><code>Ctrl+Z</code> undoes a note instead.</strong> Inside a text field the browser&#39;s native undo applies; page-level undo only works on the stage.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/panels">Panel Workbench</a> — the controls these keys drive.</li><li><a href="/KomaYomi-docs/guide/compare">Compare Reader</a> — masking and alignment.</li><li><a href="/KomaYomi-docs/guide/notes">Notes</a> — editor behaviour.</li></ul>',28)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
